window.biliPlayerDocument = "\u003c!doctype html>\n\u003chtml data-bili-embedded=\"1\" lang=\"zh-CN\">\n\u003chead>\n  \u003cmeta charset=\"utf-8\">\u003cmeta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\">\n  \u003ctitle>BiliMusic · 空间唱片 UI 方案\u003c/title>\n  \u003clink rel=\"stylesheet\" href=\"prototype.css\">\u003clink rel=\"stylesheet\" href=\"scene.css\">\n  \u003cscript src=\"prototype.js\" defer>\u003c/script>\n\u003c/head>\n\u003cbody>\n\u003cmain id=\"spatial-player\" data-theme=\"day\" data-motion=\"on\" data-view=\"listen\">\n  \u003cdiv class=\"ambient ambient-one\" aria-hidden=\"true\">\u003c/div>\u003cdiv class=\"ambient ambient-two\" aria-hidden=\"true\">\u003c/div>\n  \u003cheader class=\"app-header\">\n    \u003ca class=\"wordmark\" href=\"#\" aria-label=\"BiliMusic 空间唱片\">BiliMusic\u003cspan>.\u003c/span>\u003csmall>空间唱片\u003c/small>\u003c/a>\n    \u003cdiv class=\"header-actions\">\u003cspan class=\"prototype-tag\">交互原型\u003c/span>\u003cbutton id=\"motion-toggle\" class=\"quiet-button\" aria-pressed=\"true\">\u003cspan data-icon=\"motion\">\u003c/span>\u003cspan class=\"motion-label\">动效开启\u003c/span>\u003c/button>\u003cbutton id=\"theme-toggle\" class=\"icon-button\" aria-label=\"切换至夜间光线\" title=\"切换至夜间光线\">\u003cspan data-icon=\"moon\">\u003c/span>\u003c/button>\u003cbutton id=\"about-toggle\" class=\"icon-button\" aria-label=\"查看方案说明\" title=\"查看方案说明\">\u003cspan data-icon=\"info\">\u003c/span>\u003c/button>\u003cbutton id=\"browse-close\" class=\"icon-button\" aria-label=\"收起播放器，返回浏览\" title=\"返回浏览\" hidden>\u003cspan data-icon=\"close\">\u003c/span>\u003c/button>\u003c/div>\n  \u003c/header>\n  \u003csection class=\"listening-stage\" aria-label=\"空间播放场景\">\n    \u003cdiv class=\"scene-dock\">\n      \u003cdiv class=\"record-scene\" data-playing=\"false\" role=\"img\" aria-label=\"当前专辑的立体唱片，旋转表示播放状态\">\n        \u003cdiv class=\"scene-aura\" aria-hidden=\"true\">\u003c/div>\u003cdiv class=\"record-shadow\" aria-hidden=\"true\">\u003c/div>\n        \u003cdiv class=\"record-hover\">\u003cdiv class=\"record-object\">\u003cdiv class=\"record-edge\">\u003c/div>\u003cdiv class=\"record-rotor\">\u003cdiv class=\"record-face\">\u003cimg class=\"record-label\" src=\"../../../src/assets/forest.jpg\" alt=\"山间来信专辑封面\" draggable=\"false\">\u003cspan class=\"record-hole\">\u003c/span>\u003c/div>\u003c/div>\u003cdiv class=\"record-light\" aria-hidden=\"true\">\u003c/div>\u003c/div>\u003c/div>\n        \u003cdiv class=\"scene-caption\">\u003cspan class=\"caption-dot\">\u003c/span>\u003cspan id=\"scene-state\">把片刻，留给音乐\u003c/span>\u003c/div>\n      \u003c/div>\n    \u003c/div>\n    \u003cdiv class=\"song-space\">\n      \u003cdiv class=\"song-heading\">\u003cp class=\"eyebrow\">BILIMUSIC STUDIO · 山间来信\u003c/p>\u003ch1 id=\"track-title\">薄雾序曲\u003c/h1>\u003cp class=\"track-artist\">BiliMusic Studio \u003cspan>原创器乐 EP\u003c/span>\u003c/p>\u003cdiv class=\"quality\">\u003cspan data-icon=\"wave\">\u003c/span>\u003cspan>FLAC · 44.1 kHz\u003c/span>\u003cspan class=\"quality-dot\">\u003c/span>\u003cspan>内置试听\u003c/span>\u003c/div>\u003c/div>\n      \u003cdiv class=\"listening-copy\">\u003cp class=\"listening-line\">让声音，有了空间。\u003c/p>\u003cp class=\"listening-description\">没有分界的画面，\u003cbr>只有唱片、光线，和此刻的音乐。\u003c/p>\u003cbutton id=\"enter-lyrics\" class=\"text-button\">进入歌词视野 \u003cspan data-icon=\"arrow\">\u003c/span>\u003c/button>\u003c/div>\n      \u003cdiv class=\"lyrics-space\" aria-label=\"歌词区域\" hidden>\n        \u003cdiv class=\"lyrics-note\">\u003cspan class=\"eyebrow\">INSTRUMENTAL\u003c/span>\u003ch2>这首歌，让旋律说话。\u003c/h2>\u003cp>当前试听为器乐曲，没有歌词。\u003c/p>\u003cbutton id=\"demo-lyrics\" class=\"text-button\">预览歌词动效 \u003cspan data-icon=\"arrow\">\u003c/span>\u003c/button>\u003c/div>\n        \u003cdiv id=\"demo-lines\" class=\"lyric-lines\" hidden aria-label=\"仅用于排版和动效的示例歌词\">\u003csmall class=\"demo-label\">歌词排版演示 · 非本曲歌词\u003c/small>\u003cp class=\"lyric-before\">风从远处经过\u003c/p>\u003cp class=\"lyric-active\">把这一刻，轻轻留住\u003c/p>\u003cp class=\"lyric-after\">等下一束光，慢慢落下\u003c/p>\u003cbutton id=\"demo-advance\" class=\"text-button\">下一句 \u003cspan data-icon=\"arrow\">\u003c/span>\u003c/button>\u003c/div>\n      \u003c/div>\n    \u003c/div>\n    \u003caside id=\"side-wing\" class=\"side-wing\" aria-labelledby=\"wing-title\" hidden>\n      \u003cheader class=\"wing-head\">\u003cdiv>\u003cp id=\"wing-kicker\" class=\"eyebrow\">YOUR LISTENING SPACE\u003c/p>\u003ch2 id=\"wing-title\">接下来\u003c/h2>\u003c/div>\u003cbutton id=\"wing-close\" class=\"icon-button\" aria-label=\"收起面板\">\u003cspan data-icon=\"close\">\u003c/span>\u003c/button>\u003c/header>\n      \u003cdiv id=\"wing-body\" class=\"wing-body\">\u003c/div>\n    \u003c/aside>\n  \u003c/section>\n  \u003cfooter class=\"floating-controls\" aria-label=\"播放控制\">\n    \u003cdiv class=\"transport\">\u003cbutton id=\"repeat\" class=\"icon-button secondary\" aria-label=\"开启循环\" aria-pressed=\"false\">\u003cspan data-icon=\"repeat\">\u003c/span>\u003c/button>\u003cbutton id=\"previous\" class=\"icon-button\" aria-label=\"上一首\">\u003cspan data-icon=\"previous\">\u003c/span>\u003c/button>\u003cbutton id=\"play\" class=\"play-button\" aria-label=\"播放\">\u003cspan data-icon=\"play\">\u003c/span>\u003c/button>\u003cbutton id=\"next\" class=\"icon-button\" aria-label=\"下一首\">\u003cspan data-icon=\"next\">\u003c/span>\u003c/button>\u003cbutton id=\"favorite\" class=\"icon-button secondary\" aria-label=\"收藏歌曲\" aria-pressed=\"false\">\u003cspan data-icon=\"heart\">\u003c/span>\u003c/button>\u003c/div>\n    \u003cdiv class=\"timeline\">\u003cspan id=\"elapsed\">0:00\u003c/span>\u003cinput id=\"seek\" type=\"range\" min=\"0\" max=\"28.263\" value=\"0\" step=\".1\" aria-label=\"播放进度\">\u003cspan id=\"duration\">0:28\u003c/span>\u003c/div>\n    \u003cdiv class=\"tool-line\">\u003cdiv class=\"view-options\" aria-label=\"场景视野\">\u003cbutton id=\"listen-view\" class=\"view-button active\" aria-pressed=\"true\">聆听\u003c/button>\u003cbutton id=\"lyrics-view\" class=\"view-button\" aria-pressed=\"false\">歌词\u003c/button>\u003c/div>\u003cdiv class=\"sound-tools\">\u003cbutton id=\"mute\" class=\"icon-button\" aria-label=\"静音\">\u003cspan data-icon=\"volume\">\u003c/span>\u003c/button>\u003cinput id=\"volume\" type=\"range\" min=\"0\" max=\"1\" step=\".01\" value=\".55\" aria-label=\"音量\">\u003cbutton id=\"queue-toggle\" class=\"quiet-button\" aria-expanded=\"false\" aria-controls=\"side-wing\">\u003cspan data-icon=\"queue\">\u003c/span>\u003cspan>队列\u003c/span>\u003csmall>3\u003c/small>\u003c/button>\u003cbutton id=\"dsp-toggle\" class=\"quiet-button\" aria-expanded=\"false\" aria-controls=\"side-wing\">\u003cspan data-icon=\"sliders\">\u003c/span>\u003cspan>音效\u003c/span>\u003c/button>\u003c/div>\u003c/div>\n  \u003c/footer>\n  \u003cdiv id=\"status\" class=\"status-message\" role=\"status\" aria-live=\"polite\">\u003c/div>\n  \u003caudio id=\"audio\" preload=\"metadata\" src=\"../../../src/assets/mist.flac\">\u003c/audio>\n\u003c/main>\n\u003c/body>\n\u003c/html>\n";
